'use strict';
const API_ROOT = ['novaclient.tech','www.novaclient.tech'].includes(location.hostname) ? 'https://api.novaclient.tech/license/' : new URL('./',location.href).href;
const apiUrl = path => new URL(path, API_ROOT).href;
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = value => new Intl.NumberFormat('en-US', {maximumFractionDigits:1}).format(Number(value) || 0);
const date = value => value == null ? 'Never' : new Date(value * 1000).toLocaleDateString('en-US');
const datetime = value => value == null ? 'Never' : new Date(value * 1000).toLocaleString('en-US', {dateStyle:'short',timeStyle:'short'});
const duration = seconds => seconds >= 3600 ? num(seconds / 3600) + ' h' : num(Math.floor((seconds || 0) / 60)) + ' min';
const labels = {playing:'Playing',spectating:'Spectating',menu:'In menu',unknown:'Legacy client',offline:'Offline',active:'Active',unused:'Unused',expired:'Expired',revoked:'Revoked',disabled:'Disabled'};
const metricLabels = {playtime:'Playtime',saves:'Saves',freezes:'Freezes',lasts:'Lasts',tries:'Attempts',deaths:'Deaths'};
const metricOrder = Object.keys(metricLabels);
const widgets = {activity:'Community activity',cohorts:'License growth',online:'Online now',ranking:'Leaderboard highlights',status:'License health',versions:'Versions in use',servers:'Servers and maps',events:'Recent activity',operations:'Operations'};
const defaultOrder = Object.keys(widgets);
const viewCopy = {overview:['Overview','The community pulse.','Presence, licenses, and performance, all connected.'],players:['Players','Every player, in context.','See who is connected and where the community plays.'],licenses:['Licenses','Every key has a story.','Creation, activation, role, and activity in one clear view.'],leaderboards:['Leaderboards','The players behind Nova.','Six ways to follow community performance.'],versions:['Versions','Progress at a glance.','Track client adoption and build compatibility.']};
const defaults = () => ({theme:'dark',accent:'violet',density:'comfortable',order:[...defaultOrder],hidden:[],full:[],preset:'analytics'});
let preferences = defaults();
try {
 const stored = JSON.parse(localStorage.getItem('nova-crm-layout-v1') || 'null');
 if (stored && typeof stored === 'object') {
  for(const [key,values] of Object.entries({theme:['dark','light'],accent:['violet','blue','emerald','rose'],density:['comfortable','compact'],preset:['analytics','operations','compact']})) if(values.includes(stored[key])) preferences[key]=stored[key];
  if(Array.isArray(stored.order)) preferences.order=[...new Set([...stored.order.filter(id=>Object.hasOwn(widgets,id)),...defaultOrder])];
  for(const key of ['hidden','full']) if(Array.isArray(stored[key])) preferences[key]=[...new Set(stored[key].filter(id=>Object.hasOwn(widgets,id)))];
 }
} catch (_) { /* Disabled storage does not block the workspace. */ }
let token='',snapshot=null,timer,requestController,busy=false,generation=0;
let view='overview',rankingMetric='playtime',editing=false,dragged=null,selectedId=null,returnFocus=null;
async function refreshPremiumOrders(){if(!token)return;const run=generation;const status=$('premium-admin-status');status.textContent='Loading Premium orders…';try{const response=await fetch(apiUrl('admin/premium'),{headers:{Authorization:'Bearer '+token},cache:'no-store'});if(!response.ok)throw Error('Could not load Premium orders');const data=await response.json();if(run!==generation||!token)return;$('premium-orders').innerHTML=data.orders.map(o=>`<tr><td>#${num(o.id)} · <button class="text-button" data-open="${num(o.license_id)}">License ${num(o.license_id)}</button><br>${esc(o.label)}</td><td><code>${esc(o.discord_id)}</code></td><td>${datetime(o.created_at)}</td><td>${datetime(o.paid_at)}</td><td>${date(o.paid_until)}</td><td>${datetime(o.grace_until)}</td><td>${badge(o.status)}</td><td>${o.status==='pending'?`<button class="text-button" data-premium-approve="${num(o.id)}">Confirm received</button>`:esc(o.payment_reference||'—')}</td></tr>`).join('')||'<tr><td colspan="8">No Premium orders yet.</td></tr>';status.textContent=`${data.orders.length} recent order(s). Payment claims remain pending until you confirm the received Pix.`;}catch(e){if(run===generation&&token)status.textContent=e.message;}}
const pages={players:1,licenses:1},pageSize=25;
function badge(status,text=labels[status]||status){return `<span class="badge ${esc(status)}">${esc(text)}</span>`;}
function avatar(name,role=''){const initials=Array.from(String(name||'NC').trim()).slice(0,2).join('').toLocaleUpperCase();return `<span class="avatar ${role==='Owner'?'violet':role==='Supporter'?'green':role==='Collaborator'?'rose':''}" aria-hidden="true">${esc(initials)}</span>`;}
function personName(p){return p.name||p.stats?.name||p.label||'Key #'+p.id;}
function openButton(p,text){return `<button class="text-button" data-open="${Number(p.id)}">${esc(text??personName(p))}</button>`;}
function empty(title,text){return `<div class="empty-state"><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`;}
function livePlayers(){return snapshot.players.filter(p=>p.online);}
function metricValue(metric,value){return metric==='playtime'?duration(value):num(value);}
function periodStart(){const start=new Date(snapshot.now*1000);start.setHours(0,0,0,0);start.setDate(start.getDate()-Number($('period').value)+1);return start.getTime()/1000;}
function groupBy(items,key){const groups=new Map();for(const item of items){const label=key(item);groups.set(label,(groups.get(label)||0)+1);}return [...groups].map(([label,count])=>({label,count})).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label));}
function savePreferences(){try{localStorage.setItem('nova-crm-layout-v1',JSON.stringify(preferences));}catch(_){}applyPreferences();}
function applyPreferences(){document.documentElement.dataset.theme=preferences.theme;document.documentElement.dataset.accent=preferences.accent;document.body.classList.toggle('compact-density',preferences.density==='compact');$('density').value=preferences.density;$('accent').value=preferences.accent;$('layout-preset').value=preferences.preset;$('theme-toggle').setAttribute('aria-label',preferences.theme==='dark'?'Switch to light theme':'Switch to dark theme');}
function renderMetrics(){
 const players=snapshot.players,live=livePlayers(),active=players.filter(p=>p.status==='active').length,issued=players.filter(p=>p.created_at>=periodStart()).length;
 const totals=players.reduce((sum,p)=>sum+(p.stats?.playtime||0),0),shared=players.filter(p=>p.stats).length;
 $('nav-online').textContent=live.length;$('nav-licenses').textContent=players.length;
 const metrics=[['Players online',num(live.length),`${live.filter(p=>p.state==='playing').length} playing · ${live.filter(p=>p.state==='spectating').length} spectating`,'positive'],['Active licenses',num(active),`${num(players.length)} keys in directory`,''],['Keys created',num(issued),`In the last ${$('period').value} days`,''],['Shared playtime',duration(totals),`${num(shared)} players sharing stats · all-time`,'']];
 $('metrics').innerHTML=metrics.map(([label,value,note,tone],i)=>`<article class="metric"><span class="metric-label">${i===0?'<span class="status-dot"></span>':''}${label}</span><strong class="metric-value ${i===0?'accent':''}">${value}</strong><span class="metric-note ${tone}">${esc(note)}</span></article>`).join('');
}
function baseLineChart(points){
 const width=600,height=230,left=36,right=16,top=20,bottom=32,w=width-left-right,h=height-top-bottom;
 const max=Math.ceil(Math.max(1,...points.flatMap(p=>[p.value,p.secondary||0]))/3)*3,span=points.at(-1).time-points[0].time,x=i=>left+(span?(points[i].time-points[0].time)/span*w:w/2),y=v=>top+h-v/max*h;
 const gaps=points.some((p,i)=>i&&p.time-points[i-1].time>3600);
 const path=key=>points.map((p,i)=>`${i&&p.time-points[i-1].time<=3600?'L':'M'}${x(i).toFixed(1)},${y(p[key]||0).toFixed(1)}`).join(' ');
 let out=`<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="group" aria-label="Hourly community activity. Use arrow keys to explore samples.">`;
 for(let i=0;i<4;i++){const value=max*i/3,yy=y(value);out+=`<line class="gridline" x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}"/><text x="${left-8}" y="${yy+3}" text-anchor="end">${num(value)}</text>`;}
 if(points.length>1&&!gaps)out+=`<path class="chart-area" d="${path('value')} L${x(points.length-1)},${y(0)} L${x(0)},${y(0)}Z"/>`;
 out+=`<path class="chart-line" d="${path('value')}"/><path class="secondary-line" d="${path('secondary')}"/>`;
 for(const i of [...new Set([0,Math.floor((points.length-1)/2),points.length-1])])out+=`<text x="${x(i)}" y="${height-8}" text-anchor="${i===0?'start':i===points.length-1?'end':'middle'}">${esc(points[i].short)}</text>`;
 points.forEach((p,i)=>{const label=`${p.label}: ${num(p.value)} online, ${num(p.secondary)} playing`,prev=i? (x(i-1)+x(i))/2:left,next=i<points.length-1?(x(i)+x(i+1))/2:width-right;out+=`<g class="chart-sample" data-sample="${i}" data-date="${esc(p.label)}" data-online="${Number(p.value)}" data-playing="${Number(p.secondary||0)}" tabindex="${i===points.length-1?'0':'-1'}" aria-label="${esc(label)}"><rect class="sample-hit" x="${prev}" y="${top}" width="${Math.max(1,next-prev)}" height="${h}"/><g class="sample-marker" aria-hidden="true"><line x1="${x(i)}" x2="${x(i)}" y1="${top}" y2="${top+h}"/><circle class="online-marker" cx="${x(i)}" cy="${y(p.value)}" r="4"/><circle class="playing-marker" cx="${x(i)}" cy="${y(p.secondary||0)}" r="4"/></g></g>`;});
 return out+'</svg>';
}
function activityWidget(){
 const history=snapshot.history.filter(p=>p.time+3600>=periodStart()),peak=Math.max(0,...history.map(p=>p.peak));
 const points=history.map(p=>({time:p.time,value:p.online,secondary:p.playing,label:datetime(p.time),short:new Date(p.time*1000).toLocaleDateString('en-US',{day:'2-digit',month:'2-digit'})+' '+new Date(p.time*1000).getHours()+'h'}));
 return `<div class="chart-summary"><strong>${num(peak)}</strong><span>peak concurrent clients sampled during this period</span></div>${points.length?lineChart(points):empty('History starts here.','The first samples will appear as the dashboard refreshes.')}<details class="chart-method"><summary>About these samples</summary><p class="chart-disclaimer">Hourly peaks observed in minute samples while the CRM is queried. Online and playing peaks may occur at different minutes. Gaps between samples do not represent zero. Up to 90 days of history.</p></details>`;
}
function cohortsWidget(){
 const n=Number($('period').value),buckets=[],base=new Date(snapshot.now*1000);base.setHours(0,0,0,0);base.setDate(base.getDate()-n+1);
 for(let i=0;i<n;i++){const d=new Date(base);d.setDate(d.getDate()+i);buckets.push({time:d.getTime()/1000,issued:0,activated:0,label:d.toLocaleDateString('en-US',{day:'2-digit',month:'2-digit'})});}
 for(const p of snapshot.players)for(const [field,target] of [['created_at','issued'],['activated_at','activated']]){if(p[field]==null)continue;const d=new Date(p[field]*1000);d.setHours(0,0,0,0);const b=buckets.find(b=>b.time===d.getTime()/1000);if(b)b[target]++;}
 const allGroups=n>30?Array.from({length:Math.ceil(n/3)},(_,i)=>({label:buckets[i*3].label,issued:buckets.slice(i*3,i*3+3).reduce((s,b)=>s+b.issued,0),activated:buckets.slice(i*3,i*3+3).reduce((s,b)=>s+b.activated,0)})):buckets;
 const groups=zoomPoints(allGroups,'cohorts');
 const max=Math.max(1,...groups.flatMap(b=>[b.issued,b.activated])),width=600,height=188,left=31,right=12,top=17,bottom=29,w=(width-left-right)/groups.length;
 let chart=`<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Keys created and activated per day during this period">`;
 for(let i=0;i<4;i++){const y=height-bottom-i/3*(height-top-bottom);chart+=`<line class="gridline" x1="${left}" x2="${width-right}" y1="${y}" y2="${y}"/><text x="${left-8}" y="${y+3}" text-anchor="end">${num(max*i/3)}</text>`;}
 groups.forEach((b,i)=>{for(const [key,cls,offset] of [['issued','chart-bar',0],['activated','secondary-bar',.4]]){const h=b[key]/max*(height-top-bottom);chart+=`<rect class="${cls}" x="${left+i*w+w*(.13+offset)}" y="${height-bottom-h}" width="${Math.max(1,w*.30)}" height="${h}" rx="2" tabindex="0"><title>${esc(b.label)}: ${b[key]} ${key==='issued'?'created':'activated'}</title></rect>`;}});
 for(const i of [...new Set([0,Math.floor((groups.length-1)/2),groups.length-1])])chart+=`<text x="${left+i*w+w/2}" y="${height-8}" text-anchor="middle">${groups[i].label}</text>`;
 return `<div class="chart-summary"><strong>${num(buckets.reduce((s,b)=>s+b.issued,0))}</strong><span>created · ${num(buckets.reduce((s,b)=>s+b.activated,0))} activations during this period</span></div><div class="zoom-chart" data-zoomchart="cohorts">${chart}</svg>${chartControls('cohorts')}</div><div class="chart-legend"><span><i class="swatch"></i>Created</span><span><i class="swatch green"></i>Activated</span></div><p class="chart-disclaimer">Dates recorded by the service.${n>30?'  Each group covers three days.':''} Creations and activations are independent events.</p>`;
}
function breakdown(groups,total,tones=[]){
 if(!groups.length)return empty('No data to display.','Data will appear when clients check in.');
 return '<div class="breakdown">'+groups.map((g,i)=>`<div><div class="breakdown-label"><span>${esc(g.label)}</span><span>${num(g.count)} <small>· ${num(total?g.count/total*100:0)}%</small></span></div><svg class="bar-track ${tones[i%tones.length]||''}" viewBox="0 0 100 7" preserveAspectRatio="none" role="img" aria-label="${esc(g.label)}: ${num(g.count)}"><rect width="${total?g.count/total*100:0}" height="7" rx="3"/></svg></div>`).join('')+'</div>';
}
function onlineWidget(){const players=livePlayers().sort((a,b)=>Number(b.state==='playing')-Number(a.state==='playing')||a.id-b.id).slice(0,6);return players.length?'<div class="compact-list">'+players.map(p=>`<div class="list-row">${avatar(personName(p),p.role)}<div class="list-person"><strong>${openButton(p)}</strong><small>${esc(p.map||p.server||p.version||'No match details')}</small></div>${badge(p.state)}</div>`).join('')+'</div>':empty('The community is quiet.','No client has checked in during the last 180 seconds.');}
function rankingWidget(){const players=snapshot.leaderboards.saves.slice(0,5);return players.length?'<div class="compact-list">'+players.map((p,i)=>`<div class="list-row"><span class="rank-number ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>${avatar(p.name,p.role)}<div class="list-person"><strong>${openButton(p,p.name)}</strong><small>${esc(p.role)} · Key #${Number(p.id)}</small></div><span class="list-value">${num(p.value)} <small class="muted">saves</small></span></div>`).join('')+'</div>':empty('More community highlights are on the way.','This panel shows the leaderboard for shared saves.');}
function statusWidget(){
 const players=snapshot.players,total=players.length,groups=[['active','Active','ring-active'],['unused','Unused','ring-unused'],['expired','Expired','ring-expired'],['revoked','Revoked','ring-revoked'],['disabled','Disabled','ring-revoked']];let offset=0;
 const rings=groups.map(([key,,cls])=>{const count=players.filter(p=>p.status===key).length,fraction=total?count/total*100:0,svg=`<circle class="${cls}" cx="80" cy="80" r="62" pathLength="100" stroke-dasharray="${fraction} ${100-fraction}" stroke-dashoffset="${-offset}"><title>${esc(labels[key])}: ${count}</title></circle>`;offset+=fraction;return svg;}).join('');
 return `<div class="status-layout"><div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="img" aria-label="License status distribution"><circle cx="80" cy="80" r="62"/>${rings}</svg><div class="donut-total"><strong>${num(total)}</strong><small>licenses</small></div></div><div class="status-legend">${groups.map(([key,label])=>`<div><span>${label}</span><strong>${num(players.filter(p=>p.status===key).length)}</strong></div>`).join('')}</div></div>`;
}
function versionsWidget(){return breakdown(groupBy(snapshot.players,p=>p.version||'Not reported').slice(0,6),snapshot.players.length,['','blue','green','amber']);}
function serversWidget(){const live=livePlayers().filter(p=>p.server),groups=groupBy(live,p=>p.server).slice(0,5);return groups.length?'<div class="compact-list">'+groups.map(g=>{const maps=[...new Set(live.filter(p=>p.server===g.label).map(p=>p.map).filter(Boolean))];return `<div class="list-row"><div class="list-person"><strong>${esc(g.label)}</strong><small>${esc(maps.join(' · ')||'Map not reported')}</small></div><span class="list-value">${num(g.count)} <small class="muted">players</small></span></div>`;}).join('')+'</div>':empty('No active servers.','Servers appear when a client is playing or spectating.');}
function eventsWidget(){const events=[];for(const p of snapshot.players)for(const [field,type,description] of [['created_at','created','Key created'],['activated_at','activated','License activated'],['revoked_at','revoked','License revoked']])if(p[field]!=null&&p[field]>=periodStart())events.push({p,time:p[field],type,description});events.sort((a,b)=>b.time-a.time);return events.length?'<div class="timeline">'+events.slice(0,6).map(e=>`<div class="timeline-event"><span class="event-dot ${e.type}"></span><div>${e.description}<small>${openButton(e.p,'Key #'+e.p.id+' · '+e.p.label)}</small></div><time datetime="${new Date(e.time*1000).toISOString()}">${date(e.time)}</time></div>`).join('')+'</div>':empty('No activity during this period.','Recorded creations, activations, and revocations appear here.');}
const widgetRenderers={activity:activityWidget,cohorts:cohortsWidget,online:onlineWidget,ranking:rankingWidget,status:statusWidget,versions:versionsWidget,servers:serversWidget,events:eventsWidget};
const widgetSubtitles={activity:'Real presence samples',cohorts:'Recorded creations and activations',online:'Check-ins during the last 180 seconds',ranking:'Players with the most all-time saves',status:'Current status of all keys',versions:'Latest version reported per license',servers:'Where the community is playing',events:'License events during the selected period'};
function renderOverview(){
 $('dashboard-grid').classList.toggle('layout-editing',editing);
 $('dashboard-grid').innerHTML=preferences.order.filter(id=>!preferences.hidden.includes(id)).map(id=>`<article class="panel ${preferences.full.includes(id)?'span-full':'span-half'}" data-widget="${id}"><div class="layout-tools"><button class="drag-handle" draggable="true" data-drag="${id}" aria-label="Drag ${widgets[id]}" title="Drag panel">Drag</button><button data-move="${id}" data-direction="-1" aria-label="Move ${widgets[id]} up">↑</button><button data-move="${id}" data-direction="1" aria-label="Move ${widgets[id]} down">↓</button><button data-resize="${id}" aria-label="Alternar largura de ${widgets[id]}">${preferences.full.includes(id)?'Half width':'Full width'}</button></div><div class="panel-heading"><div><h3>${widgets[id]}</h3><span class="panel-subtitle">${widgetSubtitles[id]}</span></div>${id==='online'?'<button class="panel-link" data-view="players">View players →</button>':id==='ranking'?'<button class="panel-link" data-view="leaderboards">View rankings →</button>':id==='versions'?'<button class="panel-link" data-view="versions">Explore →</button>':id==='status'?'<button class="panel-link" data-view="licenses">View keys →</button>':''}</div>${widgetRenderers[id]()}</article>`).join('')||empty('Your workspace is ready.','Enable panels in Customize to build your overview.');
}
function filteredPlayers(){const query=$('player-search').value.trim().toLocaleLowerCase(),scope=$('player-scope').value,role=$('player-role').value;return snapshot.players.filter(p=>(scope==='all'||(scope==='online'?p.online:scope==='offline'?!p.online:p.state===scope))&&(role==='all'||p.role===role)&&[p.id,p.label,p.name,p.stats?.name,p.server,p.map,p.version].join(' ').toLocaleLowerCase().includes(query)).sort((a,b)=>Number(b.online)-Number(a.online)||a.id-b.id);}
function filteredLicenses(){const query=$('license-search').value.trim().toLocaleLowerCase(),status=$('license-status').value,sort=$('license-sort').value;return snapshot.players.filter(p=>(status==='all'||p.status===status)&&[p.id,p.label,p.name,p.stats?.name,p.version,p.role].join(' ').toLocaleLowerCase().includes(query)).sort((a,b)=>sort==='activity'?(b.last_seen||0)-(a.last_seen||0)||b.id-a.id:sort==='oldest'?a.id-b.id:sort==='label'?a.label.localeCompare(b.label,'en-US'):b.id-a.id);}
function table(container,headers,rows,kind,totalLabel){
 const count=rows.length,totalPages=Math.max(1,Math.ceil(count/pageSize));pages[kind]=Math.min(pages[kind]||1,totalPages);const start=(pages[kind]-1)*pageSize,slice=rows.slice(start,start+pageSize);
 $(container).innerHTML=count?`<div class="table-wrap" tabindex="0" role="region" aria-label="Table of ${esc(totalLabel)}"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${slice.join('')}</tbody></table></div><div class="table-summary"><span>${num(start+1)}–${num(start+slice.length)} of ${num(count)} ${esc(totalLabel)}</span><div class="pagination"><button data-page="${kind}" data-step="-1" ${pages[kind]===1?'disabled':''} aria-label="Previous page">←</button><span>${pages[kind]} / ${totalPages}</span><button data-page="${kind}" data-step="1" ${pages[kind]===totalPages?'disabled':''} aria-label="Next page">→</button></div></div>`:empty('No results found.','Adjust your search and filters to find the records you need.');
}
function renderPlayers(){table('players-table',['Player / key','Presence','Server / map','Version','Role','Last check-in'],filteredPlayers().map(p=>`<tr><td><div class="person-cell">${avatar(personName(p),p.role)}<div>${openButton(p)}<small>Key #${Number(p.id)} · ${esc(p.label)}</small></div></div></td><td>${badge(p.online?p.state:'offline')}</td><td>${esc(p.server||'—')}<small>${esc(p.map||'No match reported')}</small></td><td>${esc(p.version||'Not reported')}</td><td>${badge(p.role)}</td><td>${datetime(p.last_seen)}</td></tr>`),'players','players');}
function renderLicenses(){table('licenses-table',['License / label','Status','Role / plan','Created','Activated','Latest activity','Details'],filteredLicenses().map(p=>`<tr><td>${openButton(p,'Key #'+p.id)}<small>${esc(p.label)}</small></td><td>${badge(p.status)}</td><td>${badge(p.role)}<small>${esc(p.plan)}</small></td><td>${date(p.created_at)}</td><td>${date(p.activated_at)}</td><td>${datetime(p.last_seen)}<small>${esc(p.version||'Version not reported')}</small></td><td><button class="panel-link" data-open="${Number(p.id)}" aria-label="Open key details ${Number(p.id)}">Open →</button></td></tr>`),'licenses','licenses');}
function renderRankings(){
 $('ranking-tabs').innerHTML=metricOrder.map(metric=>`<button id="ranking-tab-${metric}" data-metric="${metric}" role="tab" aria-selected="${metric===rankingMetric}" aria-controls="ranking-detail" tabindex="${metric===rankingMetric?0:-1}">${metricLabels[metric]}</button>`).join('');
 $('ranking-detail').setAttribute('role','tabpanel');$('ranking-detail').setAttribute('aria-labelledby','ranking-tab-'+rankingMetric);
 const list=snapshot.leaderboards[rankingMetric]||[],first=list[0];
 if(!first){$('ranking-detail').innerHTML=empty('The leaderboard is open.','No shared stats are available for this category yet.');return;}
 $('ranking-detail').innerHTML=`<article class="ranking-feature"><span class="champion-label">Leader · ${esc(metricLabels[rankingMetric])}</span>${avatar(first.name,first.role)}<h3>${esc(first.name)}</h3><p>${esc(first.role)} · Key #${Number(first.id)}</p><strong>${metricValue(rankingMetric,first.value)}</strong><p>All-time ${esc(metricLabels[rankingMetric].toLocaleLowerCase())}</p><button class="text-button" data-open="${Number(first.id)}">Explore profile →</button></article><div class="data-surface"><div class="table-wrap" tabindex="0" role="region" aria-label="Rankings for ${esc(metricLabels[rankingMetric])}"><table><thead><tr><th scope="col">Position</th><th scope="col">Player</th><th scope="col">Role</th><th scope="col">${esc(metricLabels[rankingMetric])}</th></tr></thead><tbody>${list.map((p,i)=>`<tr><td><span class="rank-number ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span></td><td><div class="person-cell">${avatar(p.name,p.role)}<div>${openButton(p,p.name)}<small>${p.online?'Online now':'Key #'+Number(p.id)}</small></div></div></td><td>${badge(p.role)}</td><td><strong>${metricValue(rankingMetric,p.value)}</strong></td></tr>`).join('')}</tbody></table></div></div>`;
}
function renderVersions(){
 const groups=groupBy(snapshot.players,p=>p.version||'Not reported');$('version-distribution').innerHTML=breakdown(groups,snapshot.players.length,['','blue','green','amber']);
 $('allowed-builds').innerHTML=snapshot.allowed_builds.length?snapshot.allowed_builds.map(build=>`<div class="build-row"><code>${esc(build)}</code>${badge('allowed','Allowed')}</div>`).join(''):empty('No builds configured.','Check the license service configuration.');
 $('version-table').innerHTML=`<div class="table-wrap" tabindex="0" role="region" aria-label="Version adoption"><table><thead><tr><th scope="col">Version</th><th scope="col">Licenses</th><th scope="col">Online now</th><th scope="col">Share</th><th scope="col">V2 authorization</th></tr></thead><tbody>${groups.map(g=>`<tr><td><strong>${esc(g.label)}</strong></td><td>${num(g.count)}</td><td>${num(snapshot.players.filter(p=>(p.version||'Not reported')===g.label&&p.online).length)}</td><td>${num(snapshot.players.length?g.count/snapshot.players.length*100:0)}%</td><td>${badge(snapshot.allowed_builds.includes(g.label)?'allowed':'not-allowed',snapshot.allowed_builds.includes(g.label)?'Allowed':g.label==='Not reported'?'Not reported':'Fora da lista v2')}</td></tr>`).join('')}</tbody></table></div>`;
}
function setView(next){if(!Object.hasOwn(viewCopy,next))return;view=next;const [name,title,description]=viewCopy[next];for(const id of Object.keys(viewCopy))$('view-'+id).hidden=id!==next;document.querySelectorAll('#navigation [data-view]').forEach(button=>{const active=button.dataset.view===next;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});$('breadcrumb').textContent=name;$('page-title').textContent=title;$('page-description').textContent=description;const operational=['network','kog','titles','audit','finance','plans','commands'].includes(next);$('metrics').hidden=operational;$('period').closest('label').hidden=operational;if(snapshot)renderView();window.scrollTo({top:0,behavior:'instant'});}
function renderView(){if(!snapshot)return;renderMetrics();const renderer=({overview:renderOverview,players:renderPlayers,licenses:renderLicenses,leaderboards:renderRankings,versions:renderVersions})[view];if(renderer)renderer();else if(typeof renderOperationsView==='function')renderOperationsView(view);if(selectedId!==null&&!$('profile').hidden&&!$('profile').contains(document.activeElement)){renderProfile();if(typeof renderProfileActions==='function')renderProfileActions();}}
function renderProfile(){
 const p=snapshot.players.find(p=>p.id===selectedId);if(!p){closeProfile();return;}
 const row=(label,value)=>`<div class="detail-row"><dt>${label}</dt><dd>${esc(value)}</dd></div>`;
 $('profile-content').innerHTML=`<div class="profile-head">${avatar(personName(p),p.role)}<h2>${esc(personName(p))}</h2><p>Key #${Number(p.id)} · ${esc(p.label)}</p><div class="profile-badges">${badge(p.status)}${badge(p.role)}${p.online?badge(p.state):''}</div></div><section class="profile-section"><h3>License</h3><dl>${row('Plan',p.plan)}${row('Created',datetime(p.created_at))}${row('Activated',datetime(p.activated_at))}${row('Expires',p.expires_at==null?'Never':datetime(p.expires_at))}${p.revoked_at?row('Revoked',datetime(p.revoked_at)):''}</dl></section><section class="profile-section"><h3>Latest activity</h3><dl>${row('Check-in',datetime(p.last_seen))}${row('Version',p.version||'Not reported')}${row('Server',p.server||'—')}${row('Map',p.map||'—')}${row('Indicator',p.hidden_indicator==null?'Not reported':p.hidden_indicator?'Hidden':'Visible')}</dl></section><section class="profile-section"><h3>Shared stats</h3>${p.stats?`<div class="profile-stats">${metricOrder.map(metric=>`<div><small>${metricLabels[metric]}</small><strong>${metricValue(metric,p.stats[metric])}</strong></div>`).join('')}</div><p class="help">Updated ${datetime(p.stats.updated_at)}. All-time totals reported by the client.</p>`:'<p class="help">This player has not shared any stats yet.</p>'}</section>`;
}
function openProfile(id,trigger){selectedId=Number(id);returnFocus=trigger;$('profile').hidden=false;renderProfile();if(typeof renderProfileActions==='function')renderProfileActions();$('close-profile').focus();}
function closeProfile(){selectedId=null;$('profile').hidden=true;$('profile-content').replaceChildren();if(returnFocus?.isConnected)returnFocus.focus();returnFocus=null;}
function markStale(message){$('connection').textContent=message;$('connection').classList.add('error');$('connection-short').textContent='Data may be out of date';$('connection-dot').classList.add('stale');}
function logout(message=''){generation++;requestController?.abort();clearInterval(timer);token='';snapshot=null;busy=false;closeProfile();$('token').value='';$('app').hidden=true;$('login').hidden=false;$('login-error').textContent=message;for(const id of ['metrics','dashboard-grid','players-table','licenses-table','ranking-detail','version-distribution','allowed-builds','version-table'])$(id).replaceChildren();$('login-submit').disabled=false;$('login-submit').textContent='Open workspace →';$('token').focus();}
async function refresh(force=false){
 if(busy||!token||(!force&&document.hidden))return;
 busy=true;const run=generation;requestController=new AbortController();const controller=requestController,timeout=setTimeout(()=>controller.abort(),10000);$('refresh').disabled=true;
 try{
  const response=await fetch(apiUrl('admin/crm'),{headers:{Authorization:'Bearer '+token},cache:'no-store',signal:controller.signal});if(run!==generation)return;
  if(response.status===401){logout('Invalid admin key or access is disabled.');return;}
  if(!response.ok)throw Error('HTTP '+response.status);const data=await response.json();if(run!==generation)return;
  if(!Array.isArray(data.players)||!data.leaderboards||!Array.isArray(data.history))throw Error('Invalid response');
  snapshot=data;$('login').hidden=true;$('app').hidden=false;$('login-error').textContent='';if(!dragged){if(editing&&view==='overview')renderMetrics();else renderView();}refreshPremiumOrders();
  $('connection').textContent='Updated at '+new Date(data.now*1000).toLocaleTimeString('en-US')+' · Live service data · Auto-refresh every 10 sec';$('connection').classList.remove('error');$('connection-short').textContent='Service connected';$('connection-dot').classList.remove('stale');
 }catch(error){if(run!==generation)return;const message='Refresh failed. '+(snapshot?'Displayed data may be out of date. Try refreshing.':'Check your connection and try again.');markStale(message);$('login-error').textContent=message;}
 finally{clearTimeout(timeout);if(run===generation){busy=false;$('refresh').disabled=false;$('login-submit').disabled=false;$('login-submit').textContent='Open workspace →';}}
}
function csvCell(value){let text=String(value??'');if(/^[\s]*[=+@\-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}
function exportCSV(kind){
 if(!snapshot)return;let rows;
 if(kind==='leaderboards')rows=[['Position','Key ID','Player','Role',metricLabels[rankingMetric]],...(snapshot.leaderboards[rankingMetric]||[]).map((p,i)=>[i+1,p.id,p.name,p.role,p.value])];
 else{const players=kind==='players'?filteredPlayers():filteredLicenses();rows=[['Key ID','Label','Player','Status','Role','Plan','Online','Version','Created','Activated','Expires','Last check-in','Server','Map'],...players.map(p=>[p.id,p.label,personName(p),labels[p.status],p.role,p.plan,p.online?'Yes':'No',p.version,datetime(p.created_at),datetime(p.activated_at),p.expires_at?datetime(p.expires_at):'Never',datetime(p.last_seen),p.server,p.map])];}
 const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='novaclient-'+kind+'-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function renderToggles(){$('widget-toggles').innerHTML='<legend>Panels shown on overview</legend>'+defaultOrder.map(id=>`<label><input type="checkbox" data-toggle="${id}" ${preferences.hidden.includes(id)?'':'checked'}>${widgets[id]}</label>`).join('');}
function moveWidget(id,direction){const order=preferences.order,index=order.indexOf(id),next=index+direction;if(next<0||next>=order.length)return;[order[index],order[next]]=[order[next],order[index]];savePreferences();renderOverview();$('dashboard-grid').querySelector(`[data-move="${id}"][data-direction="${direction}"]`)?.focus();}
$('login-form').addEventListener('submit',event=>{event.preventDefault();if(busy)return;token=$('token').value.trim();if(!token)return;$('token').value='';generation++;clearInterval(timer);$('login-submit').disabled=true;$('login-submit').textContent='Connecting…';refresh(true);timer=setInterval(()=>refresh(),10000);});
$('premium-refresh').addEventListener('click',refreshPremiumOrders);
$('logout').addEventListener('click',()=>logout());$('refresh').addEventListener('click',()=>refresh(true));$('period').addEventListener('change',renderView);
$('theme-toggle').addEventListener('click',()=>{preferences.theme=preferences.theme==='dark'?'light':'dark';savePreferences();});
$('customize').addEventListener('click',()=>{const hidden=!$('customization').hidden;$('customization').hidden=hidden;$('customize').setAttribute('aria-expanded',String(!hidden));if(hidden){editing=false;$('edit-layout').setAttribute('aria-pressed','false');if(view==='overview'&&snapshot)renderOverview();}});
$('density').addEventListener('change',()=>{preferences.density=$('density').value;savePreferences();});$('accent').addEventListener('change',()=>{preferences.accent=$('accent').value;savePreferences();});
$('edit-layout').addEventListener('click',()=>{editing=!editing;$('edit-layout').setAttribute('aria-pressed',String(editing));setView('overview');});
$('reset-layout').addEventListener('click',()=>{const {theme,accent}=preferences;preferences={...defaults(),theme,accent};savePreferences();renderToggles();if(snapshot)renderView();});
$('layout-preset').addEventListener('change',()=>{const preset=$('layout-preset').value;preferences.preset=preset;preferences.hidden=[];preferences.full=[];preferences.density=preset==='compact'?'compact':'comfortable';preferences.order=preset==='operations'?['online','servers','status','events','activity','cohorts','versions','ranking']:preset==='compact'?['online','status','ranking','versions','activity','cohorts','servers','events']:[...defaultOrder];if(preset==='compact')preferences.hidden=['servers','events'];savePreferences();renderToggles();if(snapshot)setView('overview');});
$('widget-toggles').addEventListener('change',event=>{const id=event.target.dataset.toggle;if(!id)return;preferences.hidden=preferences.hidden.filter(value=>value!==id);if(!event.target.checked)preferences.hidden.push(id);savePreferences();if(snapshot&&view==='overview')renderOverview();});
for(const id of ['player-search','player-scope','player-role','license-search','license-status','license-sort'])$(id).addEventListener(id.endsWith('search')?'input':'change',()=>{pages[id.startsWith('player')?'players':'licenses']=1;renderView();});
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.view)setView(button.dataset.view);if(button.dataset.open)openProfile(button.dataset.open,button);if(button.dataset.metric){rankingMetric=button.dataset.metric;renderRankings();$('ranking-tab-'+rankingMetric).focus();}if(button.dataset.page){pages[button.dataset.page]+=Number(button.dataset.step);renderView();}if(button.dataset.export)exportCSV(button.dataset.export);if(button.dataset.move)moveWidget(button.dataset.move,Number(button.dataset.direction));if(button.dataset.resize){const id=button.dataset.resize;preferences.full=preferences.full.includes(id)?preferences.full.filter(value=>value!==id):[...preferences.full,id];savePreferences();renderOverview();$('dashboard-grid').querySelector(`[data-resize="${id}"]`)?.focus();}});
$('ranking-tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const i=metricOrder.indexOf(rankingMetric);rankingMetric=event.key==='Home'?metricOrder[0]:event.key==='End'?metricOrder.at(-1):metricOrder[(i+(event.key==='ArrowRight'?1:-1)+metricOrder.length)%metricOrder.length];renderRankings();$('ranking-tab-'+rankingMetric).focus();});
$('close-profile').addEventListener('click',closeProfile);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('profile').hidden)closeProfile();});
$('dashboard-grid').addEventListener('dragstart',event=>{const handle=event.target.closest('[data-drag]');if(!editing||!handle){event.preventDefault();return;}dragged=handle.dataset.drag;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',dragged);handle.closest('.panel').classList.add('dragging');});
$('dashboard-grid').addEventListener('dragover',event=>{if(!dragged)return;const panel=event.target.closest('[data-widget]');if(!panel)return;event.preventDefault();event.dataTransfer.dropEffect='move';document.querySelectorAll('.drag-target').forEach(p=>p.classList.remove('drag-target'));panel.classList.add('drag-target');});
$('dashboard-grid').addEventListener('drop',event=>{if(!dragged)return;event.preventDefault();const id=event.target.closest('[data-widget]')?.dataset.widget;if(id&&id!==dragged){preferences.order=preferences.order.filter(value=>value!==dragged);preferences.order.splice(preferences.order.indexOf(id),0,dragged);savePreferences();}dragged=null;renderOverview();});
$('dashboard-grid').addEventListener('dragend',()=>{dragged=null;document.querySelectorAll('.dragging,.drag-target').forEach(p=>p.classList.remove('dragging','drag-target'));});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
applyPreferences();renderToggles();
